// The overlay's font and icon atlas (loader/src/overlay_assets.c, generated by tools/make_overlay_assets.py). zlib-compressed.
#pragma once

typedef struct {
    unsigned short x, y, width, height;  // the glyph's cell in the atlas (height is the font's line, or the icon cell)
    float advance, bearing;              // pen advance; where the pen sits inside the cell
} OverlayGlyph;
// Glyphs are found by (style << 24 | code point) in overlay_glyph_codes (sorted). Styles: 0 regular, 1 bold, 2 icon (code = icon number).
// Codes 1-4 (regular style) are the controller's face buttons: cross, circle, square, triangle.
enum { OVERLAY_CROSS = 1, OVERLAY_CIRCLE = 2, OVERLAY_SQUARE = 3, OVERLAY_TRIANGLE = 4 };
enum { OVERLAY_STYLE_REGULAR = 0, OVERLAY_STYLE_BOLD = 1, OVERLAY_STYLE_ICON = 2 };
extern const unsigned overlay_font_width, overlay_font_height, overlay_font_line, overlay_font_ascent, overlay_icon_cell;
extern const unsigned overlay_glyph_count;
extern const unsigned overlay_glyph_codes[];
extern const OverlayGlyph overlay_glyphs[];
extern const unsigned overlay_font_alpha_size;  // one byte of coverage per atlas pixel
extern const unsigned char overlay_font_alpha[];
extern const unsigned overlay_logo_width, overlay_logo_height;
extern const unsigned overlay_logo_rgba_size;  // RGBA, straight alpha
extern const unsigned char overlay_logo_rgba[];
